<slate
  title="Choose a job queue database"
  state={{
    selected: "",
    note: "",
    options: [
      { name: "Postgres", setup: "Already running", concurrency: "Row locks", tradeoff: "Uses existing infrastructure" },
      { name: "SQLite", setup: "Zero setup", concurrency: "One writer", tradeoff: "Best for a simple local queue" },
      { name: "DynamoDB", setup: "Managed", concurrency: "Scales broadly", tradeoff: "Costs money" }
    ]
  }}
>
  <column id="root" tight>
    <table id="options" items={state.options} key={item.name}>
      <col
        title="Database"
        value={item.name}
        tone={item.name == state.selected ? 'good' : 'default'}
      />
      <col title="Setup" value={item.setup} />
      <col title="Concurrency" value={item.concurrency} />
      <col title="Tradeoff" value={item.tradeoff} />
      <action
        label={item.name == state.selected ? 'Selected' : 'Pick'}
        onPress={set(state.selected, item.name)}
      />
    </table>
    <input
      id="note"
      label={`Note for ${orElse(state.selected, 'your pick')}`}
      value={state.note}
      lines={3}
      placeholder="Why this option, constraints, or anything to keep in mind"
      held={state.selected == '' ? 'Pick a database first' : ''}
      submit="Send choice"
      onSubmit={send("Use my selected database for the job queue, taking my note into account.", { with: [state.selected, state.note] })}
    />
  </column>
</slate>
